-- A·B 양쪽에 같은 스키마를 만든다.
-- id: GENERATED BY DEFAULT (논리 복제가 명시 id 를 넣을 수 있어야 하므로 ALWAYS 가 아니라 BY DEFAULT).
--     이 시퀀스는 복제로 올라오지 않으므로 컷오버 때 '시퀀스 맞춤'이 필요하다(ADR-0004).
-- n : writer 가 넣는 단조 증가 번호. 누락(gap)·중복 검증의 기준.
CREATE SCHEMA IF NOT EXISTS demo;

CREATE TABLE IF NOT EXISTS demo.seq_write (
  id       bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  n        bigint NOT NULL UNIQUE,
  wrote_at timestamptz NOT NULL DEFAULT now()
);
